\begin{lemma}
\label{lemma-permanence-universal-homeomorphism}
Let $f : X \to Z$ be the composition of two morphisms 
$g : X \to Y$ and $h : Y \to Z$.
If two of the morphisms $\{f, g, h\}$ are universal homeomorphisms,
so is the third morphism.
\end{lemma}

